// Focused real Quill + Dashboard checks; synthetic storage and loopback font API only.
import React from 'react';
import { createRoot } from 'react-dom/client';
import { BrowserRouter } from 'react-router-dom';
import { Quill } from 'react-quill-new';
import Dashboard from '../../src/components/Dashboard.jsx';
import { convertEditorFont } from '../../src/Editor/fontConversion.js';
import { requestFontConversion } from '../../src/Editor/fontConversion.js';
import { exportSnapshot } from '../../src/Editor/exportDownload.js';
import { pdfBlob } from '../../src/Editor/pdfExport.js';
import { wordBlob } from '../../src/Editor/wordExport.js';
const owner='000000000000000000000001', key='autosave_'+owner;
const word='\u0928\u092e\u0938\u094d\u0924\u0947';
const stylesheet=document.createElement('link');stylesheet.rel='stylesheet';stylesheet.href='/editor-fonts.css';document.head.appendChild(stylesheet);
const results=JSON.parse(sessionStorage.getItem('kruti-results')||'[]');
const check=(name,pass)=>{results.push({bug:'Kruti',name,pass:!!pass});sessionStorage.setItem('kruti-results',JSON.stringify(results));if(!pass)throw Error(name)};
const sleep=ms=>new Promise(resolve=>setTimeout(resolve,ms));
const wait=async predicate=>{for(let i=0;i<200;i++){if(predicate())return;await sleep(25)}throw Error('Timed out')};
const realFetch=window.fetch;
window.fetch=(input,options)=>{if(new URL(input,location.href).origin!==location.origin)throw Error('External traffic blocked');return realFetch(input,options)};
window.alert=message=>{throw Error(message)};
window.SpeechRecognition=class{start(){window.__nativeRecognition=this;this.onstart?.()}stop(){this.onend?.()}};
localStorage.setItem('user',JSON.stringify({_id:owner,role:'user',subscription:{isActive:true}}));
let root=createRoot(document.getElementById('root'));
const mount=()=>root.render(<BrowserRouter><Dashboard/></BrowserRouter>);
const q=()=>Quill.find(document.querySelector('.ql-container'));
const remount=async()=>{root.unmount();root=createRoot(document.getElementById('root'));mount();await wait(()=>document.querySelector('.ql-editor'));await sleep(80)};
const report=()=>{document.body.innerHTML='<pre id="verification-result"></pre>';document.getElementById('verification-result').textContent=JSON.stringify(results)};
mount();
(async()=>{try{
  await wait(()=>document.querySelector('.ql-editor'));await sleep(80);
  if(sessionStorage.getItem('kruti-reload')){
    check('page reload restores exact mixed text',q().getText()===sessionStorage.getItem('kruti-text'));
    check('page reload restores selected font and original bold format',q().getFormat(13,5).font==='krutidev'&&q().getFormat(13,5).bold);
    check('page reload does not apply KrutiDev to English or hint',!q().root.style.fontFamily&&!q().getFormat(0,5).font);
    const marathi='मराठी अर्ज', index=q().getLength()-1;
    q().insertText(index,' '+marathi,'user');q().setSelection(index+1,marathi.length);await sleep(50);
    await convertEditorFont(q(),'unicode-to-krutidev',(text,type)=>requestFontConversion(location.origin,text,type));await sleep(50);
    check('Marathi conversion retains surrounding Hindi/English and uses inline KrutiDev',q().getText().includes('English '+word)&&q().getFormat(index+1,1).font==='krutidev');
    const marathiText=q().getText();await wait(()=>localStorage.getItem(key)?.includes(q().root.querySelectorAll('.ql-font-krutidev')[1]?.textContent));
    await remount();
    check('reopened Hindi/Marathi conversion keeps exact text, glyph font and formatting',q().getText()===marathiText&&q().getFormat(index+1,1).font==='krutidev'&&q().getFormat(13,5).bold);
    const loaded=await document.fonts.load('16px KrutiDev');
    check('bundled KrutiDev font actually loads for rendering',loaded.length>0&&loaded.every(font=>font.status==='loaded'));
    const option=document.querySelector('option[value="unicode-to-preeti"]');
    check('unavailable Preeti is visibly disabled',option?.disabled&&option.textContent.includes('unavailable'));
    check('unverified Shivaji01 is visibly disabled',document.querySelector('option[value="unicode-to-shivaji"]')?.disabled);
    const snapshot=exportSnapshot(q()),beforeExport=JSON.stringify(q().getContents());
    for(const [name,blob] of [['font.pdf',await pdfBlob(snapshot.blocks,snapshot.defaults)],['font.docx',await wordBlob(snapshot.blocks,snapshot.defaults)]]){
      const response=await fetch('/font-artifacts/'+name,{method:'POST',headers:{'Content-Type':'application/octet-stream'},body:blob});
      check(name+' export generates a downloadable artifact',response.ok&&blob.size>1000);
    }
    let blocked=false;try{await pdfBlob(snapshot.blocks,{font:'Preeti'})}catch(error){blocked=error.message.includes('Preeti is unavailable')}
    check('Preeti PDF export refuses fallback without changing the document',blocked&&JSON.stringify(q().getContents())===beforeExport);
    check('PDF and Word export preserve editor content and formatting',JSON.stringify(q().getContents())===beforeExport);
    const open=window.open;let opened=false;window.open=()=>{opened=true;throw Error('Unverified print opened')};
    q().root.style.fontFamily='Shivaji01, sans-serif';document.querySelector('[title="Print"]').click();await sleep(50);
    check('unverified Shivaji print fails clearly before opening output',!opened&&document.querySelector('[role="alert"]')?.textContent.includes('Shivaji is unavailable')&&JSON.stringify(q().getContents())===beforeExport);
    q().root.style.fontFamily='';window.open=open;
    q().setText('left right','user');q().formatText(0,5,{bold:true},'user');await sleep(50);q().setSelection(5,0);q().blur();
    const language=document.querySelector('aside select');language.value='mr-IN';language.dispatchEvent(new Event('change',{bubbles:true}));await sleep(50);
    [...document.querySelectorAll('button')].find(button=>button.textContent.includes('Start Speaking')).click();await wait(()=>window.__nativeRecognition);
    const result=Object.assign([{transcript:'अर्ज पूर्ण विराम नवीन परिच्छेद पुढे'}],{isFinal:true});
    window.__nativeRecognition.onresult({resultIndex:0,results:[result]});await wait(()=>q().getText().includes('पुढे'));
    check('native Marathi recognition commands insert at remembered cursor',q().getText()==='left अर्ज.\n\nपुढे right\n');
    check('native command insertion retains surrounding bold formatting',q().getFormat(0,4).bold&&q().getSelection()?.index===q().getText().indexOf('right'));
    [...document.querySelectorAll('button')].find(button=>button.textContent.includes('Stop Speaking')).click();
    q().setText('left right','user');await sleep(50);q().setSelection(5,0);q().blur();
    language.value='hi';language.dispatchEvent(new Event('change',{bubbles:true}));await sleep(50);
    const previousRecognition=window.__nativeRecognition;
    [...document.querySelectorAll('button')].find(button=>button.textContent.includes('Start Speaking')).click();await wait(()=>window.__nativeRecognition!==previousRecognition);
    check('Hindi retains production browser fallback and hi-IN language',window.__nativeRecognition.lang==='hi-IN');
    window.__nativeRecognition.onresult({resultIndex:0,results:[Object.assign([{transcript:'पहला पूर्ण विराम नई पंक्ति दूसरा'}],{isFinal:true})]});await wait(()=>q().getText().includes('दूसरा'));
    check('native Hindi commands retain text on both sides of the caret',q().getText()==='left पहला.\nदूसरा right\n');
    [...document.querySelectorAll('button')].find(button=>button.textContent.includes('Stop Speaking')).click();
    const legacy='<h2><strong>ueLrs</strong></h2><p>Existing saved draft</p>';
    // Flush the active editor before seeding a separate historical synthetic draft.
    root.unmount();
    localStorage.setItem(key,legacy);localStorage.setItem('autosave_font_'+owner,JSON.stringify({version:1,html:legacy,fontFamily:'KrutiDev, sans-serif'}));
    root=createRoot(document.getElementById('root'));mount();await wait(()=>document.querySelector('.ql-editor'));await sleep(80);
    check('old root-font autosave remains recoverable without migration',q().getText()==='ueLrs\nExisting saved draft\n'&&q().root.style.fontFamily==='KrutiDev, sans-serif'&&q().getFormat(0,3).bold);
    check('restoring old draft does not erase its stored HTML',localStorage.getItem(key)===legacy);
    report();return;
  }
  check('empty editor contains no actual placeholder text',q().getText()==='\n'&&q().root.dataset.placeholder==='Start typing or speaking...');
  await convertEditorFont(q(),'unicode-to-krutidev',()=>{throw Error('Placeholder sent to converter')});
  check('empty conversion preserves hint, empty Delta and root font',q().getText()==='\n'&&!q().root.style.fontFamily);
  q().setText('Start Typing','user');await sleep(50);
  await convertEditorFont(q(),'unicode-to-krutidev',()=>{throw Error('English sent to converter')});
  check('legitimate saved Start Typing text is preserved',q().getText()==='Start Typing\n'&&!q().root.style.fontFamily);
  q().setContents({ops:[{insert:'Start Typing ',attributes:{italic:true}},{insert:word,attributes:{bold:true}},{insert:' English '+word},{insert:'\n',attributes:{align:'center'}}]},'user');
  await sleep(50);q().setSelection(0,0);
  const unselected=JSON.stringify(q().getContents());let needsSelection=false;
  try{await convertEditorFont(q(),'unicode-to-krutidev',()=>{throw Error('Unselected document sent')})}catch(error){needsSelection=error.message.startsWith('Select the text')}
  check('no selection leaves the entire existing document untouched',needsSelection&&JSON.stringify(q().getContents())===unselected);
  await sleep(50);q().setSelection(13,word.length);q().blur();await sleep(40);
  const before=JSON.stringify(q().getContents()), historyBefore=q().history.stack.undo.length;
  [...document.querySelectorAll('button')].find(button=>button.textContent.includes('Convert Font')).click();
  await wait(()=>q().getText().includes('ueLrs'));await sleep(80);
  const after=JSON.stringify(q().getContents());
  check('only selected Devanagari converts; both English and unselected Marathi survive',q().getText()==='Start Typing ueLrs English '+word+'\n');
  check('conversion keeps inline and paragraph formatting',q().getFormat(0,5).italic&&q().getFormat(13,5).bold&&q().getFormat(13,5).font==='krutidev'&&q().getFormat(0,1).align==='center');
  check('English and placeholder keep the default root font',!q().root.style.fontFamily&&!q().getFormat(0,5).font);
  await document.fonts.ready;
  check('actual stylesheet renders converted text in KrutiDev only',getComputedStyle(q().root.querySelector('.ql-font-krutidev')).fontFamily.includes('KrutiDev')&&!getComputedStyle(q().root).fontFamily.includes('KrutiDev'));
  check('selection maps to the converted range',q().getSelection()?.index===13&&q().getSelection()?.length===5);
  check('conversion adds one undo step and preserves earlier history',q().history.stack.undo.length===historyBefore+1);
  q().history.undo();check('undo restores original text and formatting',JSON.stringify(q().getContents())===before);
  q().history.redo();check('redo restores conversion',JSON.stringify(q().getContents())===after);
  const requests=await fetch('/__requests').then(response=>response.json());
  check('real font API receives only selected Unicode text',requests.length===1&&requests[0].text===word);
  await wait(()=>localStorage.getItem(key)?.includes('ql-font-krutidev'));
  const html=localStorage.getItem(key),text=q().getText();
  await remount();check('reopen restores the saved mixed document and formatting',q().getText()===text&&q().getFormat(13,5).font==='krutidev'&&q().getFormat(13,5).bold);
  check('reopen preserves existing autosave instead of resetting it',localStorage.getItem(key)===html);
  sessionStorage.setItem('kruti-text',text);sessionStorage.setItem('kruti-reload','1');location.reload();return;
}catch(error){results.push({bug:'Kruti',name:error.message,pass:false})}report()})();
